    internal static int JsInformative(emon.Port.Cells nodes, emon.Port.Cells regions, int n) {
        // 1 when a block's inline children carry information: any that is
        // not a plain `text` node, or has a geometry of its own (SPEC 4.2).
        int c = Model.NodeFirstChild(nodes, n);
        while (c >= 0) {
            if (Model.NkIsInline(Model.NodeKind(nodes, c)) == 1) {
                if (Model.NodeKind(nodes, c) != Model.NkText()) {
                    return 1;
                }
                if (Model.NodeRegionCount(nodes, c) > 0) {
                    return 1;
                }
            }
            c = Model.NodeNext(nodes, c);
        }
        return 0;
    }
    internal static int JsHasInline(emon.Port.Cells nodes, int n) {
        int c = Model.NodeFirstChild(nodes, n);
        while (c >= 0) {
            if (Model.NkIsInline(Model.NodeKind(nodes, c)) == 1) {
                return 1;
            }
            c = Model.NodeNext(nodes, c);
        }
        return 0;
    }
    internal static int JsDerived(System.Text.StringBuilder t, emon.Port.Cells nodes, emon.Port.Cells text, int n) {
        // The plain text of a node's inline children, written (escaped) into
        // a JSON string: a text or ref node's own run, a linebreak as a
        // newline, and a span or link by descending into its children.
        int c = Model.NodeFirstChild(nodes, n);
        int kc = 0;
        while (c >= 0) {
            kc = Model.NodeKind(nodes, c);
            if (kc == Model.NkLinebreak()) {
                emon.Port.TextAscii(t, "\\n");
            }
            if (Model.NkIsInline(kc) == 1) {
                if (Model.NodeHasText(nodes, c) == 1) {
                    JsRun(t, text, Model.NodeTextStart(nodes, c), Model.NodeTextLen(nodes, c));
                }
                if (Model.NodeFirstChild(nodes, c) != -1) {
                    JsDerived(t, nodes, text, c);
                }
            }
            c = Model.NodeNext(nodes, c);
        }
        return 0;
    }
    internal static int JsAt(System.Text.StringBuilder t, int pr, int d, emon.Port.Cells nodes, emon.Port.Cells regions, int n, int started) {
