        while (r >= 0) {
            JsFsep(t, pr, i);
            emon.Port.TextAscii(t, "[");
            emon.Port.TextI32(t, Model.RegionPage(regions, r));
            JsFsep(t, pr, 1);
            JsCpt(t, Model.RegionX0(regions, r));
            JsFsep(t, pr, 1);
            JsCpt(t, Model.RegionY0(regions, r));
            JsFsep(t, pr, 1);
            JsCpt(t, Model.RegionX1(regions, r));
            JsFsep(t, pr, 1);
            JsCpt(t, Model.RegionY1(regions, r));
            emon.Port.TextAscii(t, "]");
            i += 1;
            r = Model.RegionNext(regions, r);
        }
        emon.Port.TextAscii(t, "]");
        return 1;
    }
