        emon.Port.TextAscii(t, "\"");
        s = JsKfields(t, pr, d, nodes, attrs, text, n, kind, s);
        if (Model.NodeHasText(nodes, n) == 1) {
            s = JsBegin(t, pr, d, s, Model.FkText());
            JsStr(t, text, Model.NodeTextStart(nodes, n), Model.NodeTextLen(nodes, n));
        } else if ((inl == 0) && (hasin == 1)) {
            s = JsBegin(t, pr, d, s, Model.FkText());
            emon.Port.TextAscii(t, "\"");
            JsDerived(t, nodes, text, n);
            emon.Port.TextAscii(t, "\"");
        }
        if ((inl == 0) && (info == 1)) {
            s = JsBegin(t, pr, d, s, Model.FkInlines());
            emon.Port.TextAscii(t, "[");
            c = Model.NodeFirstChild(nodes, n);
            while (c >= 0) {
                if (Model.NkIsInline(Model.NodeKind(nodes, c)) == 1) {
                    JsAelem(t, pr, d + 1, k);
                    JsNode(t, pr, d + 2, nodes, attrs, regions, text, c);
                    k += 1;
                }
                c = Model.NodeNext(nodes, c);
            }
            JsAend(t, pr, d + 1, k);
        }
        k = 0;
        c = Model.NodeFirstChild(nodes, n);
        while (c >= 0) {
            if ((inl == 1) || (Model.NkIsInline(Model.NodeKind(nodes, c)) == 0)) {
                if (k == 0) {
                    s = JsBegin(t, pr, d, s, Model.FkChildren());
                    emon.Port.TextAscii(t, "[");
                }
                JsAelem(t, pr, d + 1, k);
                JsNode(t, pr, d + 2, nodes, attrs, regions, text, c);
                k += 1;
            }
            c = Model.NodeNext(nodes, c);
        }
        if (k > 0) {
            JsAend(t, pr, d + 1, k);
        }
        s = JsTail(t, pr, d, nodes, regions, n, s);
        JsClose(t, pr, d, s);
        return 0;
    }
    internal static int JsFurniture(System.Text.StringBuilder t, int pr, int d, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int n) {
        // A furniture root as SPEC 4.2 writes it: `id`, `role`, `template`
        // (its own text), `pages`, then any blocks it holds and the
        // provenance. No `kind`: the array says what it is.
        int s = 0;
        int c = 0;
        int k = 0;
        emon.Port.TextAscii(t, "{");
        s = JsBegin(t, pr, d, s, Model.FkId());
        emon.Port.TextI32(t, n);
        s = JsERole(t, pr, d, s, Model.NodeSub(nodes, n));
        if (Model.NodeHasText(nodes, n) == 1) {
            s = JsBegin(t, pr, d, s, Model.FkTemplate());
            JsStr(t, text, Model.NodeTextStart(nodes, n), Model.NodeTextLen(nodes, n));
        }
        s = JsFarrInt(t, pr, d, nodes, attrs, n, Model.FkPages(), s);
        c = Model.NodeFirstChild(nodes, n);
        while (c >= 0) {
            if (k == 0) {
                s = JsBegin(t, pr, d, s, Model.FkChildren());
                emon.Port.TextAscii(t, "[");
            }
            JsAelem(t, pr, d + 1, k);
            JsNode(t, pr, d + 2, nodes, attrs, regions, text, c);
            k += 1;
            c = Model.NodeNext(nodes, c);
        }
        if (k > 0) {
            JsAend(t, pr, d + 1, k);
        }
        s = JsTail(t, pr, d, nodes, regions, n, s);
        JsClose(t, pr, d, s);
        return 0;
    }
    internal static int JsPage(System.Text.StringBuilder t, int pr, int d, emon.Port.Cells pages, emon.Port.Cells text, int p) {
        // One row of the page table: `n`, `label`, `w`, `h`, `rot`, `kind`,
        // `health`, `dpi`, `px` (the pixel size of a raster page).
        int s = 0;
        emon.Port.TextAscii(t, "{");
        s = JsBegin(t, pr, d, s, Model.FkN());
        emon.Port.TextI32(t, Model.PageNumber(pages, p));
        if (Model.PageLabelStart(pages, p) >= 0) {
            s = JsBegin(t, pr, d, s, Model.FkLabel());
            JsStr(t, text, Model.PageLabelStart(pages, p), Model.PageLabelLen(pages, p));
        }
        s = JsBegin(t, pr, d, s, Model.FkW());
        JsCpt(t, Model.PageW(pages, p));
        s = JsBegin(t, pr, d, s, Model.FkH());
        JsCpt(t, Model.PageH(pages, p));
        s = JsBegin(t, pr, d, s, Model.FkRot());
        emon.Port.TextI32(t, Model.PageRot(pages, p));
        if (Model.PageKind(pages, p) > 0) {
            s = JsBegin(t, pr, d, s, Model.FkKind());
            emon.Port.TextAscii(t, "\"");
            Model.PkEmitName(t, Model.PageKind(pages, p));
            emon.Port.TextAscii(t, "\"");
        }
        if (Model.PageHealth(pages, p) >= 0) {
            s = JsBegin(t, pr, d, s, Model.FkHealth());
            emon.Port.TextI32(t, Model.PageHealth(pages, p));
        }
        if (Model.PageDpi(pages, p) > 0) {
            s = JsBegin(t, pr, d, s, Model.FkDpi());
            emon.Port.TextI32(t, Model.PageDpi(pages, p));
        }
        if ((Model.PagePxW(pages, p) > 0) || (Model.PagePxH(pages, p) > 0)) {
            s = JsBegin(t, pr, d, s, Model.FkPx());
            emon.Port.TextAscii(t, "[");
            emon.Port.TextI32(t, Model.PagePxW(pages, p));
            JsFsep(t, pr, 1);
            emon.Port.TextI32(t, Model.PagePxH(pages, p));
            emon.Port.TextAscii(t, "]");
        }
        JsClose(t, pr, d, s);
        return 0;
    }
    internal static int JsDropped(System.Text.StringBuilder t, int pr, int d, emon.Port.Cells ledger, emon.Port.Cells text, int l) {
        // One ledger row: `reason`, `page`, `at` (one region, page first),
        // `text`, `conf`, `src` (SPEC 4.2).
        int s = 0;
        emon.Port.TextAscii(t, "{");
        s = JsBegin(t, pr, d, s, Model.FkReason());
        emon.Port.TextAscii(t, "\"");
        Model.DrEmitName(t, Model.LedgerReason(ledger, l));
        emon.Port.TextAscii(t, "\"");
        s = JsBegin(t, pr, d, s, Model.FkPage());
        emon.Port.TextI32(t, Model.LedgerPage(ledger, l));
        s = JsBegin(t, pr, d, s, Model.FkAt());
        emon.Port.TextAscii(t, "[");
        emon.Port.TextI32(t, Model.LedgerPage(ledger, l));
        JsFsep(t, pr, 1);
        JsCpt(t, Model.LedgerX0(ledger, l));
        JsFsep(t, pr, 1);
        JsCpt(t, Model.LedgerY0(ledger, l));
        JsFsep(t, pr, 1);
        JsCpt(t, Model.LedgerX1(ledger, l));
        JsFsep(t, pr, 1);
        JsCpt(t, Model.LedgerY1(ledger, l));
        emon.Port.TextAscii(t, "]");
        if (Model.LedgerTextStart(ledger, l) >= 0) {
            s = JsBegin(t, pr, d, s, Model.FkText());
            JsStr(t, text, Model.LedgerTextStart(ledger, l), Model.LedgerTextLen(ledger, l));
        }
        if (Model.LedgerConf(ledger, l) >= 0) {
            s = JsBegin(t, pr, d, s, Model.FkConf());
            emon.Port.TextI32(t, Model.LedgerConf(ledger, l));
        }
        if (Model.LedgerSrc(ledger, l) != 0) {
            s = JsBegin(t, pr, d, s, Model.FkSrc());
            JsBitsSrc(t, pr, Model.LedgerSrc(ledger, l));
        }
        JsClose(t, pr, d, s);
        return 0;
    }
    internal static int JsHas(emon.Port.Cells nodes, emon.Port.Cells attrs, int key) {
        if (Model.NodeAttr(nodes, attrs, 0, key) >= 0) {
            return 1;
        }
        return 0;
    }
    internal static int JsSource(System.Text.StringBuilder t, int pr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text) {
        // `source`, from the root's attributes: format, version, pages,
        // tagged, encrypted, lang. Depth 1 (a member of the top object).
        int s = 0;
        emon.Port.TextAscii(t, "{");
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkFormat(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkVersion(), s);
        s = JsFint(t, pr, 1, nodes, attrs, 0, Model.FkPages(), s);
        s = JsFbool(t, pr, 1, nodes, attrs, 0, Model.FkTagged(), s);
        s = JsFbool(t, pr, 1, nodes, attrs, 0, Model.FkEncrypted(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkLang(), s);
        JsClose(t, pr, 1, s);
        return 0;
    }
    internal static int JsSettings(System.Text.StringBuilder t, int pr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text) {
        // `settings`: `locale` is ALWAYS written, `null` when there is none
        // (SPEC 4.2: null is itself the answer); `ocr` and `detail` if set.
        int s = 0;
        int a = Model.NodeAttr(nodes, attrs, 0, Model.FkLocale());
        emon.Port.TextAscii(t, "{");
        s = JsBegin(t, pr, 1, s, Model.FkLocale());
        if (a < 0) {
            emon.Port.TextAscii(t, "null");
        }
        if (a >= 0) {
            JsStr(t, text, Model.AttrValue(attrs, a), Model.AttrLen(attrs, a));
        }
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkOcr(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkDetail(), s);
        JsClose(t, pr, 1, s);
        return 0;
    }
    internal static int JsMeta(System.Text.StringBuilder t, int pr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text) {
        int s = 0;
        emon.Port.TextAscii(t, "{");
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkTitle(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkAuthor(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkSubject(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkKeywords(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkCreator(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkProducer(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkCreated(), s);
        s = JsFtext(t, pr, 1, nodes, attrs, text, 0, Model.FkModified(), s);
        JsClose(t, pr, 1, s);
        return 0;
    }
    public static int JsEmit(System.Text.StringBuilder t, int pretty, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger) {
        // Write the Model as canonical JSON (SPEC 4.2, 4.3). `pretty` is 1
        // for the indented form, 0 for the compact one. The root (node 0)
        // must be a document: run `model-check` first on a Model of unknown
        // origin. Answers 0.
        int s = 0;
        int i = 0;
        int k = 0;
        int nn = Model.NodeCount(nodes);
        int np = Model.PageCount(pages);
        int nl = Model.LedgerCount(ledger);
        emon.Port.TextAscii(t, "{");
        s = JsBegin(t, pretty, 0, s, Model.FkEmon());
        emon.Port.TextAscii(t, "\"1.0\"");
        s = JsFtext(t, pretty, 0, nodes, attrs, text, 0, Model.FkGenerator(), s);
        if ((JsHas(nodes, attrs, Model.FkFormat()) == 1) || (JsHas(nodes, attrs, Model.FkVersion()) == 1) || (JsHas(nodes, attrs, Model.FkPages()) == 1) || (JsHas(nodes, attrs, Model.FkTagged()) == 1) || (JsHas(nodes, attrs, Model.FkEncrypted()) == 1) || (JsHas(nodes, attrs, Model.FkLang()) == 1)) {
            s = JsBegin(t, pretty, 0, s, Model.FkSource());
            JsSource(t, pretty, nodes, attrs, text);
        }
        s = JsBegin(t, pretty, 0, s, Model.FkSettings());
        JsSettings(t, pretty, nodes, attrs, text);
        s = JsBegin(t, pretty, 0, s, Model.FkConf());
        emon.Port.TextAscii(t, "\"uncalibrated\"");
        if ((JsHas(nodes, attrs, Model.FkTitle()) == 1) || (JsHas(nodes, attrs, Model.FkAuthor()) == 1) || (JsHas(nodes, attrs, Model.FkSubject()) == 1) || (JsHas(nodes, attrs, Model.FkKeywords()) == 1) || (JsHas(nodes, attrs, Model.FkCreator()) == 1) || (JsHas(nodes, attrs, Model.FkProducer()) == 1) || (JsHas(nodes, attrs, Model.FkCreated()) == 1) || (JsHas(nodes, attrs, Model.FkModified()) == 1)) {
            s = JsBegin(t, pretty, 0, s, Model.FkMeta());
            JsMeta(t, pretty, nodes, attrs, text);
        }
        s = JsBegin(t, pretty, 0, s, Model.FkPages());
        emon.Port.TextAscii(t, "[");
        while (i < np) {
            JsAelem(t, pretty, 1, i);
            JsPage(t, pretty, 2, pages, text, i);
            i += 1;
        }
        JsAend(t, pretty, 1, np);
        s = JsBegin(t, pretty, 0, s, Model.FkBody());
        JsNode(t, pretty, 1, nodes, attrs, regions, text, 0);
        s = JsBegin(t, pretty, 0, s, Model.FkFurniture());
        emon.Port.TextAscii(t, "[");
        i = 0;
        while (i < nn) {
            if ((Model.NodeKind(nodes, i) == Model.NkFurniture()) && (Model.NodeParent(nodes, i) == -1)) {
                JsAelem(t, pretty, 1, k);
                JsFurniture(t, pretty, 2, nodes, attrs, regions, text, i);
                k += 1;
            }
            i += 1;
        }
        JsAend(t, pretty, 1, k);
        s = JsBegin(t, pretty, 0, s, Model.FkDropped());
        emon.Port.TextAscii(t, "[");
        i = 0;
        while (i < nl) {
            JsAelem(t, pretty, 1, i);
            JsDropped(t, pretty, 2, ledger, text, i);
            i += 1;
        }
        JsAend(t, pretty, 1, nl);
        JsClose(t, pretty, 0, s);
        return 0;
    }
}
